/**
 * @method
 * @name scwin.goMenu
 * @author Inswave
 * @date 2026. 09. 29
 * @param id val2
 * @returns
 * @hidden N
*/
scwin.goMenu = function (id, val2) {
    /* sdd-asis-lifecycle:begin fn_GoMenu — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let url = "";
    if (id === "11") {
        url = "/disclosure/todaydisclosure.do?method=searchTodayDisclosureMain";
    } else {
        if (id === "12") {
            url = "/disclosure/searchdisclosurebycorp.do?method=searchDisclosureByCorpMain";
        } else {
            if (id === "14") {
                url = "/disclosure/marketcalendar.do?method=readMarketCalendar_main";
            } else {
                if (id === "21") {
                    url = "/corpgeneral/listedIssueStatus.do?method=loadInitPage";
                } else {
                    if (id === "22") {
                        url = "/corpgeneral/corplist.do?method=loadInitPage";
                    } else {
                        if (id === "23") {
                            url = "/corpgeneral/capitalstockchg.do?method=loadInitPage";
                        } else {
                            if (id === "31") {
                                url = "/finanalysis/totalinfo.do?method=loadInitPage";
                            } else {
                                if (id === "41") {
                                    url = "/ipos/preinvestig.do?method=loadInitPage";
                                } else {
                                    if (id === "42") {
                                        url = "/ipos/newlisting.do?method=loadInitPage";
                                    } else {
                                        if (id === "43") {
                                            url = "/corpgeneral/irroom.do?method=searchIRScheduleMain";
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    parent.document.location.href = url;
    /* sdd-asis-lifecycle:end */
};
